    marks: [Plot.line(an, {x: "mes", y: "value", stroke: "anio", strokeWidth: 2.2}), Plot.dot(an, {x: "mes", y: "value", fill: "anio", r: 3,
      title: d =&gt; `${meses[d.mes]} ${d.anio}: ${locES.format(",.0f")(d.value)}`})]});
}







