generarPregunta = (s, rows, tipo, rng) =&gt; {
  const terrs = [...new Set(rows.map(r =&gt; r.territorio))];
  const obj = s.regional ? (terrs.includes("Andalucía") ? "Andalucía" : terrs[0]) : (terrs.includes("España") ? "España" : terrs[0]);
