  return tooltipMapa(html`&lt;div class="mapa-es mapa-ccee"&gt;${principal}&lt;div class="mapa-inset"&gt;&lt;span&gt;Canarias&lt;/span&gt;${islas}&lt;/div&gt;&lt;/div&gt;`);
}























