sel = datos.ok ? datos.rows.filter(r =&gt; terr.includes(r.territorio)) : []
datos.ok ? (terr.length ? Plot.plot({
  height: 430, marginLeft: 60, marginRight: 130,
  x: {label: null, type: "time"},
  y: {label: ind.unidad, grid: true, zero: ind.cero ?? false, tickFormat: v =&gt; fmt(v)},
  color: {domain: terr, range: colores(terr)},
  marks: [
    ind.cero ? Plot.ruleY([0], {stroke: "#999"}) : null,
    Plot.line(sel, {x: "fecha", y: "valor", stroke: "territorio", strokeWidth: 2.2, sort: "fecha"}),
    Plot.text(sel, Plot.selectLast({x: "fecha", y: "valor", z: "territorio", text: "territorio", textAnchor: "start", dx: 6, fill: "territorio"})),
    Plot.tip(sel, Plot.pointer({x: "fecha", y: "valor", title: d =&gt; `${d.territorio} · ${d.periodo}\n${fmt(d.valor)} (${ind.unidad})`}))
  ]
}) : html`&lt;p class="pending"&gt;Elige al menos un territorio.&lt;/p&gt;`)
: html`&lt;div class="callout callout-warning"&gt;&lt;p&gt;&lt;b&gt;No se han podido cargar los datos de Eurostat&lt;/b&gt; (${datos.error}). Inténtalo de nuevo más tarde o consulta la tabla directamente en &lt;a href="https://ec.europa.eu/eurostat/databrowser/view/${ind.code}/default/table" target="_blank"&gt;Eurostat&lt;/a&gt;.&lt;/p&gt;&lt;/div&gt;`

Mapa

mapaPeriodos = datos.ok ? [...new Set(datos.rows.map(r =&gt; r.periodo))].sort().reverse() : []
viewof mapaP = ind.sinGeo ? html`` : Inputs.select(["Último dato disponible", ...mapaPeriodos], {label: "Periodo del mapa"})
mapaGeo = (datos.ok && !ind.sinGeo) ? geoNuts(ind.regional ? 2 : 0) : null























mapaVals = {
  const m = new Map();
  if (!datos.ok || ind.sinGeo) return m;
  const rows = (mapaP === "Último dato disponible" || !mapaP) ? ultimos : datos.rows.filter(r =&gt; r.periodo === mapaP);
  for (const r of rows) if (r.codigo_territorio) m.set(r.codigo_territorio, r);
  return m;
}
mapaColor = {
  const v = [...mapaVals.values()].map(r =&gt; r.valor);
  return (ind.cero && d3.min(v) &lt; 0 && d3.max(v) &gt; 0)
    ? {type: "diverging", scheme: "RdBu", pivot: 0, legend: true, label: ind.unidad, tickFormat: x =&gt; fmt(x)}
    : {type: "quantile", n: 5, scheme: "PuRd", legend: true, label: ind.unidad, tickFormat: x =&gt; fmt(x)};
}
mapa = {
  if (ind.sinGeo) return html`&lt;p class="pending"&gt;Este indicador no tiene desglose territorial.&lt;/p&gt;`;
  if (!datos.ok) return html``;
  if (!mapaGeo) return html`&lt;p class="pending"&gt;No se han podido cargar los límites geográficos para el mapa.&lt;/p&gt;`;
  const nombre = f =&gt; nombresGeo[f.properties.geo] ?? f.properties.NAME_LATN ?? f.properties.NAME ?? f.properties.geo;
  const tit = f =&gt; { const r = mapaVals.get(f.properties.geo); return r ? `${nombre(f)} (${r.periodo})\n${fmt(r.valor)} ${ind.unidad}` : `${nombre(f)}\nSin datos`; };
  const marcas = (feats, clip = false) =&gt; [
    Plot.geo(feats, {fill: "#ECE7E9", stroke: "white", strokeWidth: 0.6, title: tit, clip}),
    Plot.geo(feats.filter(f =&gt; mapaVals.has(f.properties.geo)), {fill: f =&gt; mapaVals.get(f.properties.geo).valor, stroke: "white", strokeWidth: 0.6, title: tit, clip}),
    Plot.geo(feats.filter(f =&gt; ["ES", "ES61"].includes(f.properties.geo)), {stroke: "#3C3C3B", strokeWidth: 1.6, clip})
  ];
  if (!ind.regional) {
    const feats = mapaGeo.features;
    return tooltipMapa(html`&lt;div class="mapa-ccee"&gt;${Plot.plot({
      width: 760, height: 620, color: mapaColor,
      projection: {type: "azimuthal-equal-area", rotate: [-10, -52], domain: {type: "MultiPoint", coordinates: [[-11, 35], [33, 35], [33, 70], [-11, 70], [25, 34]]}},
      marks: marcas(feats, true)
    })}&lt;/div&gt;`);
  }
  const es = mapaGeo.features.filter(f =&gt; f.properties.geo?.startsWith("ES"));
  const pen = es.filter(f =&gt; f.properties.geo !== "ES70");
  // Ceuta y Melilla son muy pequeñas: se marcan además con un círculo para que se vean y se puedan consultar
  const ciudades = es.filter(f =&gt; ["ES63", "ES64"].includes(f.properties.geo)).map(f =&gt; {
    const [lon, lat] = d3.geoCentroid(f), r = mapaVals.get(f.properties.geo);
    return {lon, lat, f, valor: r ? r.valor : null};
  });
  const marcasCiudades = [
    Plot.dot(ciudades.filter(c =&gt; c.valor === null), {x: "lon", y: "lat", r: 9, fill: "#ECE7E9", stroke: "#3C3C3B", strokeWidth: 1.2, title: c =&gt; tit(c.f)}),
    Plot.dot(ciudades.filter(c =&gt; c.valor !== null), {x: "lon", y: "lat", r: 9, fill: "valor", stroke: "#3C3C3B", strokeWidth: 1.2, title: c =&gt; tit(c.f)}),
    Plot.text(ciudades, {x: "lon", y: "lat", text: c =&gt; nombresGeo[c.f.properties.geo], dy: 18, fontSize: 11, fill: "#3C3C3B"})
  ];
  const can = es.filter(f =&gt; f.properties.geo === "ES70");
  const principal = Plot.plot({width: 700, height: 560, color: mapaColor,
    projection: {type: "conic-conformal", rotate: [3.5, 0], parallels: [36, 43], domain: {type: "FeatureCollection", features: pen}},
    marks: [...marcas(es), ...marcasCiudades]});
  const islas = can.length ? Plot.plot({width: 220, height: 130, color: {...mapaColor, legend: false},
    projection: {type: "conic-conformal", rotate: [15.5, 0], parallels: [27, 29], domain: {type: "FeatureCollection", features: can}},
    marks: marcas(can)}) : "";
  return tooltipMapa(html`&lt;div class="mapa-es mapa-ccee"&gt;${principal}&lt;div class="mapa-inset"&gt;&lt;span&gt;Canarias&lt;/span&gt;${islas}&lt;/div&gt;&lt;/div&gt;`);
}























